1	package govflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"io/fs"
10		"os"
11		"path/filepath"
12		"sort"
13		"strings"
14		"sync"
15		"syscall"
16	)
17	
18	// 资金库状态文件相关错误。
19	var (
20		// ErrTreasuryAlreadyInit：初始化目标路径已存在文件，新文件才能初始化。
21		ErrTreasuryAlreadyInit = errors.New("treasury init refused: state file already exists")
22		// ErrStateCorrupt：状态文件损坏或不是受支持的资金库状态文件。
23		ErrStateCorrupt = errors.New("treasury state file is corrupt")
24		// ErrProposalNotFound：按编号查询或执行时提案不存在。
25		ErrProposalNotFound = errors.New("proposal not found")
26		// ErrProposalConflict：同编号提案再次登记但时间锁或动作原文与首次不同。
27		ErrProposalConflict = errors.New("proposal already registered with different timelock or actions")
28		// ErrInvalidRegistration：登记参数非法（编号为空、初始余额越界等）。
29		ErrInvalidRegistration = errors.New("invalid registration")
30	)
31	
32	const (
33		stateMagic   = "govflow-treasury-state"
34		stateVersion = 1
35		lockSuffix   = ".lock"
36	)
37	
38	// BalanceUpdate 记录一个账户在一次动作前后的余额。
39	type BalanceUpdate struct {
40		Account string `json:"account"`
41		Before  int64  `json:"before"`
42		After   int64  `json:"after"`
43	}
44	
45	// ActionReceipt 是凭据中对单项动作的留痕：动作原文、在提案中的顺序编号（0 起），
46	// 以及该动作引发的资金库与收款账户余额变动。
47	type ActionReceipt struct {
48		Index     int           `json:"index"`
49		Action    string        `json:"action"`
50		Treasury  BalanceUpdate `json:"treasury"`
51		Recipient BalanceUpdate `json:"recipient"`
52	}
53	
54	// Receipt 是一项提案首次成功执行后生成的执行凭据。
55	// 一项提案只允许成功一次；重试返回同一份凭据。
56	type Receipt struct {
57		ProposalID string          `json:"proposal_id"`
58		ExecutedAt int64           `json:"executed_at"` // 首次成功执行时调用方提供的时间
59		Order      int             `json:"order"`       // 成功提交的先后顺序，0 起
60		Actions    []ActionReceipt `json:"actions"`
61	}
62	
63	// ProposalRecord 是已登记提案的对外视图。State 只可能是 passed 或 executed。
64	type ProposalRecord struct {
65		ID          string   `json:"id"`
66		State       string   `json:"state"`
67		TimelockEnd int64    `json:"timelock_end"`
68		Actions     []string `json:"actions"`
69	}
70	
71	// ---- 磁盘结构（JSON） ----
72	
73	type storedProposal struct {
74		ID          string   `json:"id"`
75		State       string   `json:"state"`
76		TimelockEnd int64    `json:"timelock_end"`
77		Actions     []string `json:"actions"`
78	}
79	
80	type storedState struct {
81		Magic           string                         `json:"magic"`
82		Version         int                            `json:"version"`
83		InitialTreasury int64                          `json:"initial_treasury"`
84		Treasury        int64                          `json:"treasury"`
85		Balances        map[string]int64               `json:"balances"`
86		Proposals       map[string]*storedProposal     `json:"proposals"`
87		Receipts        []*Receipt                     `json:"receipts"`
88		VoteProposals   map[string]*storedVoteProposal `json:"vote_proposals"`
89	}
90	
91	// Store 是绑定到单个本地状态文件的资金库句柄。
92	// 多个 goroutine 可并发使用同一个 Store；不同 Store/进程操作同一状态文件时，
93	// 通过进程内互斥锁与文件锁（flock）串行化。
94	type Store struct {
95		path   string
96		mu     sync.Mutex // 保护本句柄上的全部操作
97		lockFD *os.File   // 跨进程文件锁
98		closed bool
99	}
100	
101	// 进程内按规范路径共享的互斥锁，保证同进程内多个 Store 句柄也互相串行。
102	var (
103		pathLocksMu sync.Mutex
104		pathLocks   = map[string]*sync.Mutex{}
105	)
106	
107	// canonicalPath 将路径规范化为绝对路径，保证不同拼写（如 t.json 与 ./t.json）
108	// 命中同一把进程内锁与同一个锁文件。有意不解析符号链接：文件在初始化前后必须
109	// 解析到同一个键，硬链接/绑定挂载等更深层别名不在本地单文件场景的处理范围内。
110	func canonicalPath(path string) (string, error) {
111		return filepath.Abs(path)
112	}
113	
114	func inProcessLock(path string) *sync.Mutex {
115		pathLocksMu.Lock()
116		defer pathLocksMu.Unlock()
117		m, ok := pathLocks[path]
118		if !ok {
119			m = &sync.Mutex{}
120			pathLocks[path] = m
121		}
122		return m
123	}
124	
125	// InitTreasury 创建一个全新的状态文件并写入初始资金库余额。
126	// 只有新文件才能初始化：路径已存在（含损坏文件）一律拒绝，不会重置或覆盖。
127	// treasury 必须落在有符号 64 位整数范围内且不得为负。
128	func InitTreasury(path string, treasury int64) (*Store, error) {
129		if treasury < 0 {
130			return nil, fmt.Errorf("%w: initial treasury balance must not be negative", ErrInvalidRegistration)
131		}
132		path, err := canonicalPath(path)
133		if err != nil {
134			return nil, err
135		}
136		pathMu := inProcessLock(path)
137		pathMu.Lock()
138		defer pathMu.Unlock()
139	
140		// 先打开/创建锁文件并取跨进程锁，再创建状态文件，消除“空文件已出现、
141		// 尚未写入”期间被其它进程 Open 判为损坏的窗口。
142		lockFD, err := os.OpenFile(path+lockSuffix, os.O_RDWR|os.O_CREATE, 0o600)
143		if err != nil {
144			return nil, err
145		}
146		if err := syscall.Flock(int(lockFD.Fd()), syscall.LOCK_EX); err != nil {
147			_ = lockFD.Close()
148			return nil, err
149		}
150		// O_EXCL 保证与并发初始化竞争时只有一方成功。
151		fd, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
152		if err != nil {
153			_ = syscall.Flock(int(lockFD.Fd()), syscall.LOCK_UN)
154			_ = lockFD.Close()
155			if errors.Is(err, fs.ErrExist) {
156				return nil, fmt.Errorf("%w: %s", ErrTreasuryAlreadyInit, path)
157			}
158			return nil, err
159		}
160		_ = fd.Close()
161	
162		store := &Store{path: path, lockFD: lockFD}
163		if err := store.commitLocked(newStoredState(treasury)); err != nil {
164			_ = store.funlock()
165			_ = lockFD.Close()
166			_ = os.Remove(path)
167			return nil, err
168		}
169		// 初始化完成后立即释放跨进程锁；后续每次操作各自短持锁。
170		if err := store.funlock(); err != nil {
171			_ = lockFD.Close()
172			_ = os.Remove(path)
173			return nil, err
174		}
175		return store, nil
176	}
177	
178	// Open 打开已有的资金库状态文件。文件损坏时明确拒绝，不会重建或覆盖原文件。
179	func Open(path string) (*Store, error) {
180		path, err := canonicalPath(path)
181		if err != nil {
182			return nil, err
183		}
184		pathMu := inProcessLock(path)
185		pathMu.Lock()
186		defer pathMu.Unlock()
187		return openStoreHoldingPathLock(path)
188	}
189	
190	// openStoreHoldingPathLock 的调用方必须持有该路径的进程内互斥锁。
191	func openStoreHoldingPathLock(path string) (*Store, error) {
192		if _, err := os.Stat(path); err != nil {
193			return nil, err
194		}
195		lockFD, err := os.OpenFile(path+lockSuffix, os.O_RDWR|os.O_CREATE, 0o600)
196		if err != nil {
197			return nil, err
198		}
199		if err := syscall.Flock(int(lockFD.Fd()), syscall.LOCK_EX); err != nil {
200			_ = lockFD.Close()
201			return nil, err
202		}
203		store := &Store{path: path, lockFD: lockFD}
204		if _, err := store.loadLocked(); err != nil {
205			_ = store.funlock()
206			_ = lockFD.Close()
207			return nil, err
208		}
209		// 打开时已做严格校验；锁随即释放，每次操作再各自短持锁。
210		if err := store.funlock(); err != nil {
211			_ = lockFD.Close()
212			return nil, err
213		}
214		return store, nil
215	}
216	
217	// Path 返回状态文件路径。
218	func (s *Store) Path() string { return s.path }
219	
220	// Close 释放文件锁。关闭后其它操作返回错误。
221	func (s *Store) Close() error {
222		s.mu.Lock()
223		defer s.mu.Unlock()
224		if s.closed {
225			return nil
226		}
227		s.closed = true
228		if err := s.funlock(); err != nil {
229			_ = s.lockFD.Close()
230			return err
231		}
232		return s.lockFD.Close()
233	}
234	
235	func (s *Store) flock(how int) error {
236		if s.lockFD == nil {
237			return errors.New("treasury store is closed")
238		}
239		return syscall.Flock(int(s.lockFD.Fd()), how)
240	}
241	
242	func (s *Store) funlock() error {
243		if s.lockFD == nil {
244			return nil
245		}
246		return syscall.Flock(int(s.lockFD.Fd()), syscall.LOCK_UN)
247	}
248	
249	// begin 串行化一次读改写操作：先取进程内路径锁，再取跨进程排他文件锁。
250	// 返回的 commit 在操作结束时释放锁。
251	func (s *Store) begin() (func(), error) {
252		pathMu := inProcessLock(s.path)
253		pathMu.Lock()
254		s.mu.Lock()
255		if s.closed {
256			s.mu.Unlock()
257			pathMu.Unlock()
258			return nil, errors.New("treasury store is closed")
259		}
260		if err := s.flock(syscall.LOCK_EX); err != nil {
261			s.mu.Unlock()
262			pathMu.Unlock()
263			return nil, err
264		}
265		return func() {
266			_ = s.funlock()
267			s.mu.Unlock()
268			pathMu.Unlock()
269		}, nil
270	}
271	
272	func newStoredState(treasury int64) *storedState {
273		return &storedState{
274			Magic:           stateMagic,
275			Version:         stateVersion,
276			InitialTreasury: treasury,
277			Treasury:        treasury,
278			Balances:        map[string]int64{},
279			Proposals:       map[string]*storedProposal{},
280			Receipts:        []*Receipt{},
281			VoteProposals:   map[string]*storedVoteProposal{},
282		}
283	}
284	
285	// ---- 登记 ----
286	
287	// Register 登记一项已通过（passed）的提案，保留时间锁与动作原文。
288	// 编号必须非空；动作列表可为空（执行时会因动作为空被拒绝），动作原文不做改写。
289	// 同编号且时间锁、动作原文与首次登记完全相同的重试返回 existed=true；
290	// 内容不同则返回 ErrProposalConflict。
291	func (s *Store) Register(id string, timelockEnd int64, actions []string) (existed bool, err error) {
292		if id == "" {
293			return false, fmt.Errorf("%w: proposal id must not be empty", ErrInvalidRegistration)
294		}
295		commit, err := s.begin()
296		if err != nil {
297			return false, err
298		}
299		defer commit()
300	
301		state, err := s.loadLocked()
302		if err != nil {
303			return false, err
304		}
305		stored := copyActions(actions)
306		if existing, ok := state.Proposals[id]; ok {
307			if existing.TimelockEnd == timelockEnd && sameActions(existing.Actions, stored) {
308				return true, nil
309			}
310			return false, fmt.Errorf("%w: proposal %s", ErrProposalConflict, id)
311		}
312		// 两种来源共用编号：register 不能覆盖投票提案或绕过其投票结论。
313		if vp, ok := state.VoteProposals[id]; ok {
314			return false, fmt.Errorf("%w: proposal id %s belongs to a voting proposal (state=%s)", ErrProposalConflict, id, vp.State)
315		}
316		state.Proposals[id] = &storedProposal{
317			ID:          id,
318			State:       "passed",
319			TimelockEnd: timelockEnd,
320			Actions:     stored,
321		}
322		if err := s.commitLocked(state); err != nil {
323			return false, err
324		}
325		return false, nil
326	}
327	
328	func copyActions(actions []string) []string {
329		if actions == nil {
330			return nil
331		}
332		copied := make([]string, len(actions))
333		copy(copied, actions)
334		return copied
335	}
336	
337	// sameActions 将 nil 与空切片视为等价，其余按顺序逐字比较。
338	func sameActions(a, b []string) bool {
339		if len(a) != len(b) {
340			return false
341		}
342		for i := range a {
343			if a[i] != b[i] {
344				return false
345			}
346		}
347		return true
348	}
349	
350	// ---- 执行 ----
351	
352	// executionTarget 是 register 与投票两种来源提案在执行路径上的统一视图。
353	type executionTarget struct {
354		state        string
355		timelockEnd  int64
356		actions      []string
357		markExecuted func()
358	}
359	
360	// resolveExecutable 在两种提案表中按编号定位执行目标；不存在返回 nil。
361	func resolveExecutable(state *storedState, id string) *executionTarget {
362		if p, ok := state.Proposals[id]; ok {
363			return &executionTarget{
364				state:        p.State,
365				timelockEnd:  p.TimelockEnd,
366				actions:      p.Actions,
367				markExecuted: func() { p.State = "executed" },
368			}
369		}
370		if vp, ok := state.VoteProposals[id]; ok {
371			return &executionTarget{
372				state:        vp.State,
373				timelockEnd:  vp.TimelockEnd,
374				actions:      vp.Actions,
375				markExecuted: func() { vp.State = "executed" },
376			}
377		}
378		return nil
379	}
380	
381	// proposalOwners 将两个来源的提案编号映射到状态，供凭据重放交叉校验。
382	func proposalOwnerState(state *storedState, id string) (string, []string, bool) {
383		if p, ok := state.Proposals[id]; ok {
384			return p.State, p.Actions, true
385		}
386		if vp, ok := state.VoteProposals[id]; ok {
387			return vp.State, vp.Actions, true
388		}
389		return "", nil, false
390	}
391	
392	// Execute 按编号执行一项提案。调用方通过 now 提供当前时间。
393	// 只有 passed 状态、now 已达到时间锁且动作非空的提案可以首次执行；
394	// 成功后状态变为 executed 并返回凭据。资格不符、动作格式错误、余额不足、
395	// 金额计算溢出都返回明确原因，整项提案不产生部分转账，也不消耗执行机会。
396	// 已完成提案再次执行（即使 now 不同）直接返回首次成功凭据。
397	func (s *Store) Execute(id string, now int64) (*Receipt, error) {
398		commit, err := s.begin()
399		if err != nil {
400			return nil, err
401		}
402		defer commit()
403	
404		state, err := s.loadLocked()
405		if err != nil {
406			return nil, err
407		}
408		target := resolveExecutable(state, id)
409		if target == nil {
410			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
411		}
412		if target.state == "executed" {
413			if rcpt := findReceipt(state.Receipts, id); rcpt != nil {
414				return cloneReceipt(rcpt), nil
415			}
416			return nil, fmt.Errorf("%w: executed proposal %s has no receipt", ErrStateCorrupt, id)
417		}
418		if target.state != "passed" {
419			return nil, execReject(fmt.Sprintf("proposal %s is not passed (state=%s)", id, target.state))
420		}
421		if now < target.timelockEnd {
422			return nil, execReject(fmt.Sprintf("timelock not reached for %s: now=%d timelock_end=%d", id, now, target.timelockEnd))
423		}
424		if len(target.actions) == 0 {
425			return nil, execReject(fmt.Sprintf("proposal %s has no actions", id))
426		}
427	
428		// 第一阶段：在副本上校验并预演全部动作。任何一步失败都不得落盘。
429		type step struct {
430			account        string
431			amount         int64
432			treasuryBefore int64
433			treasuryAfter  int64
434			accountBefore  int64
435			accountAfter   int64
436		}
437		simTreasury := state.Treasury
438		simBalances := map[string]int64{}
439		for k, v := range state.Balances {
440			simBalances[k] = v
441		}
442		steps := make([]step, 0, len(target.actions))
443		for i, raw := range target.actions {
444			account, amount, perr := ParseTransfer(raw)
445			if perr != nil {
446				// 双 %w：调用方既可按 ErrExecutionRejected 判定执行被拒，
447				// 也可按 ErrInvalidAction 区分“动作格式错误”这一具体原因。
448				return nil, fmt.Errorf("%w: action %d (%q): %w", ErrExecutionRejected, i, raw, perr)
449			}
450			balanceBefore := simBalances[account]
451			balanceAfter, ok := addInt64(balanceBefore, amount)
452			if !ok {
453				return nil, execReject(fmt.Sprintf("recipient balance overflow at action %d: account=%s balance=%d amount=%d", i, account, balanceBefore, amount))
454			}
455			if simTreasury < amount {
456				return nil, execReject(fmt.Sprintf("insufficient treasury balance at action %d: treasury=%d amount=%d", i, simTreasury, amount))
457			}
458			treasuryBefore := simTreasury
459			simTreasury -= amount
460			simBalances[account] = balanceAfter
461			steps = append(steps, step{
462				account:        account,
463				amount:         amount,
464				treasuryBefore: treasuryBefore,
465				treasuryAfter:  simTreasury,
466				accountBefore:  balanceBefore,
467				accountAfter:   balanceAfter,
468			})
469		}
470	
471		// 第二阶段：全部预演成功后构造凭据并一次性原子提交。
472		receipt := &Receipt{
473			ProposalID: id,
474			ExecutedAt: now,
475			Order:      len(state.Receipts),
476			Actions:    make([]ActionReceipt, 0, len(steps)),
477		}
478		for i, st := range steps {
479			receipt.Actions = append(receipt.Actions, ActionReceipt{
480				Index:  i,
481				Action: target.actions[i],
482				Treasury: BalanceUpdate{
483					Account: "treasury",
484					Before:  st.treasuryBefore,
485					After:   st.treasuryAfter,
486				},
487				Recipient: BalanceUpdate{
488					Account: st.account,
489					Before:  st.accountBefore,
490					After:   st.accountAfter,
491				},
492			})
493		}
494		state.Treasury = simTreasury
495		state.Balances = simBalances
496		target.markExecuted()
497		state.Receipts = append(state.Receipts, receipt)
498	
499		if err := s.commitLocked(state); err != nil {
500			return nil, err
501		}
502		return cloneReceipt(receipt), nil
503	}
504	
505	func findReceipt(receipts []*Receipt, id string) *Receipt {
506		for _, r := range receipts {
507			if r.ProposalID == id {
508				return r
509			}
510		}
511		return nil
512	}
513	
514	func cloneReceipt(r *Receipt) *Receipt {
515		if r == nil {
516			return nil
517		}
518		copied := *r
519		if r.Actions != nil {
520			copied.Actions = make([]ActionReceipt, len(r.Actions))
521			copy(copied.Actions, r.Actions)
522		}
523		return &copied
524	}
525	
526	// ---- 查询 ----
527	
528	// TreasuryBalance 返回资金库当前余额。
529	func (s *Store) TreasuryBalance() (int64, error) {
530		state, err := s.readState()
531		if err != nil {
532			return 0, err
533		}
534		return state.Treasury, nil
535	}
536	
537	// Balance 返回收款账户余额；从未出现过的账户余额为零。
538	func (s *Store) Balance(account string) (int64, error) {
539		state, err := s.readState()
540		if err != nil {
541			return 0, err
542		}
543		return state.Balances[account], nil
544	}
545	
546	// Balances 返回全部出现过的收款账户余额的副本，按账户名排序。
547	func (s *Store) Balances() (map[string]int64, error) {
548		state, err := s.readState()
549		if err != nil {
550			return nil, err
551		}
552		out := make(map[string]int64, len(state.Balances))
553		for k, v := range state.Balances {
554			out[k] = v
555		}
556		return out, nil
557	}
558	
559	// Proposal 按编号返回提案登记信息；不存在时 ok 为 false。
560	func (s *Store) Proposal(id string) (ProposalRecord, bool, error) {
561		state, err := s.readState()
562		if err != nil {
563			return ProposalRecord{}, false, err
564		}
565		p, ok := state.Proposals[id]
566		if !ok {
567			return ProposalRecord{}, false, nil
568		}
569		return toProposalRecord(p), true, nil
570	}
571	
572	// Proposals 返回全部已登记提案，按编号排序。
573	func (s *Store) Proposals() ([]ProposalRecord, error) {
574		state, err := s.readState()
575		if err != nil {
576			return nil, err
577		}
578		out := make([]ProposalRecord, 0, len(state.Proposals))
579		for _, p := range state.Proposals {
580			out = append(out, toProposalRecord(p))
581		}
582		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
583		return out, nil
584	}
585	
586	func toProposalRecord(p *storedProposal) ProposalRecord {
587		return ProposalRecord{
588			ID:          p.ID,
589			State:       p.State,
590			TimelockEnd: p.TimelockEnd,
591			Actions:     copyActions(p.Actions),
592		}
593	}
594	
595	// Receipt 按编号返回执行凭据；尚未成功执行或不存在时 ok 为 false。
596	func (s *Store) Receipt(id string) (*Receipt, bool, error) {
597		state, err := s.readState()
598		if err != nil {
599			return nil, false, err
600		}
601		r := findReceipt(state.Receipts, id)
602		if r == nil {
603			return nil, false, nil
604		}
605		return cloneReceipt(r), true, nil
606	}
607	
608	// Receipts 按成功提交的先后顺序返回全部执行凭据的副本。
609	func (s *Store) Receipts() ([]*Receipt, error) {
610		state, err := s.readState()
611		if err != nil {
612			return nil, err
613		}
614		out := make([]*Receipt, 0, len(state.Receipts))
615		for _, r := range state.Receipts {
616			out = append(out, cloneReceipt(r))
617		}
618		return out, nil
619	}
620	
621	func (s *Store) readState() (*storedState, error) {
622		commit, err := s.begin()
623		if err != nil {
624			return nil, err
625		}
626		defer commit()
627		return s.loadLocked()
628	}
629	
630	// ---- 持久化 ----
631	
632	// loadLocked 读取、严格解析并重放校验状态文件。调用方必须持锁。
633	func (s *Store) loadLocked() (*storedState, error) {
634		raw, err := os.ReadFile(s.path)
635		if err != nil {
636			return nil, err
637		}
638		if len(bytes.TrimSpace(raw)) == 0 {
639			return nil, fmt.Errorf("%w: %s: file is empty", ErrStateCorrupt, s.path)
640		}
641		if err := rejectDuplicateKeys(raw); err != nil {
642			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
643		}
644		var state storedState
645		dec := json.NewDecoder(bytes.NewReader(raw))
646		dec.DisallowUnknownFields()
647		if err := dec.Decode(&state); err != nil {
648			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
649		}
650		// 拒绝单个合法 JSON 之后再拼接的额外内容（如 "{} {}"）。
651		var extra json.RawMessage
652		if err := dec.Decode(&extra); err != io.EOF {
653			if err == nil {
654				err = fmt.Errorf("unexpected trailing content after state document: %s", strings.TrimSpace(string(extra)))
655			}
656			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
657		}
658		if err := validateState(&state); err != nil {
659			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
660		}
661		return &state, nil
662	}
663	
664	// commitLocked 序列化状态并以“临时文件 + fsync + 原子改名 + 目录 fsync”提交。
665	// 任一步失败都保留上次完整状态。调用方必须持锁。
666	func (s *Store) commitLocked(state *storedState) error {
667		if err := validateState(state); err != nil {
668			return fmt.Errorf("refusing to persist invalid state: %w", err)
669		}
670		payload, err := json.MarshalIndent(state, "", "  ")
671		if err != nil {
672			return err
673		}
674		payload = append(payload, '\n')
675	
676		dir := filepath.Dir(s.path)
677		tmp, err := os.CreateTemp(dir, ".govflow-state-*")
678		if err != nil {
679			return err
680		}
681		tmpName := tmp.Name()
682		cleanup := func() { _ = os.Remove(tmpName) }
683		if _, err := tmp.Write(payload); err != nil {
684			_ = tmp.Close()
685			cleanup()
686			return err
687		}
688		if err := tmp.Sync(); err != nil {
689			_ = tmp.Close()
690			cleanup()
691			return err
692		}
693		if err := tmp.Close(); err != nil {
694			cleanup()
695			return err
696		}
697		if err := os.Chmod(tmpName, 0o600); err != nil {
698			cleanup()
699			return err
700		}
701		if err := os.Rename(tmpName, s.path); err != nil {
702			cleanup()
703			return err
704		}
705		if err := syncDir(dir); err != nil {
706			return err
707		}
708		return nil
709	}
710	
711	func syncDir(dir string) error {
712		d, err := os.Open(dir)
713		if err != nil {
714			return err
715		}
716		defer d.Close()
717		return d.Sync()
718	}
719	
720	// validateState 做结构校验并重放全部凭据，确认余额与凭据完全一致。
721	func validateState(state *storedState) error {
722		if state.Magic != stateMagic {
723			return fmt.Errorf("bad magic %q", state.Magic)
724		}
725		if state.Version != stateVersion {
726			return fmt.Errorf("unsupported state version %d", state.Version)
727		}
728		if state.InitialTreasury < 0 {
729			return errors.New("initial treasury balance is negative")
730		}
731		if state.Treasury < 0 {
732			return errors.New("treasury balance is negative")
733		}
734		if state.Balances == nil {
735			return errors.New("balances table is missing")
736		}
737		if state.Proposals == nil {
738			return errors.New("proposals table is missing")
739		}
740		if state.Receipts == nil {
741			return errors.New("receipts table is missing")
742		}
743		// VoteProposals 缺省视为空表：旧版本写出的状态文件不含投票提案，继续可读。
744		if state.VoteProposals == nil {
745			state.VoteProposals = map[string]*storedVoteProposal{}
746		}
747		for account, balance := range state.Balances {
748			if account == "" {
749				return errors.New("balance entry with empty account")
750			}
751			if balance < 0 {
752				return fmt.Errorf("balance of %q is negative", account)
753			}
754		}
755		for key, p := range state.Proposals {
756			if p == nil {
757				return fmt.Errorf("proposal %q is empty", key)
758			}
759			if p.ID != key || p.ID == "" {
760				return fmt.Errorf("proposal key %q does not match id %q", key, p.ID)
761			}
762			if p.State != "passed" && p.State != "executed" {
763				return fmt.Errorf("proposal %q has unknown state %q", p.ID, p.State)
764			}
765			// 动作原文登记时原样保存；空串或非法原文留待执行时拒绝。
766		}
767		if err := validateVoteProposals(state); err != nil {
768			return err
769		}
770	
771		// 重放凭据：从初始资金库余额出发，按成功顺序重放每笔转账，
772		// 校验凭据内的前后余额、最终资金库与各账户余额，并检查状态一致性。
773		simTreasury := state.InitialTreasury
774		simBalances := map[string]int64{}
775		seenReceipts := map[string]int{}
776		for order, rcpt := range state.Receipts {
777			if rcpt == nil {
778				return fmt.Errorf("receipt %d is empty", order)
779			}
780			if rcpt.Order != order {
781				return fmt.Errorf("receipt %q order field is %d, expected %d", rcpt.ProposalID, rcpt.Order, order)
782			}
783			if prev, dup := seenReceipts[rcpt.ProposalID]; dup {
784				return fmt.Errorf("duplicate receipt for %q at positions %d and %d", rcpt.ProposalID, prev, order)
785			}
786			seenReceipts[rcpt.ProposalID] = order
787			ownerState, ownerActions, found := proposalOwnerState(state, rcpt.ProposalID)
788			if !found {
789				return fmt.Errorf("receipt %q references an unregistered proposal", rcpt.ProposalID)
790			}
791			if ownerState != "executed" {
792				return fmt.Errorf("proposal %q has receipt but state is %q", rcpt.ProposalID, ownerState)
793			}
794			if len(rcpt.Actions) != len(ownerActions) {
795				return fmt.Errorf("receipt %q action count %d does not match proposal %d", rcpt.ProposalID, len(rcpt.Actions), len(ownerActions))
796			}
797			for i, ar := range rcpt.Actions {
798				if ar.Index != i {
799					return fmt.Errorf("receipt %q action %d has index %d", rcpt.ProposalID, i, ar.Index)
800				}
801				if ar.Action != ownerActions[i] {
802					return fmt.Errorf("receipt %q action %d text does not match registered action", rcpt.ProposalID, i)
803				}
804				account, amount, err := ParseTransfer(ar.Action)
805				if err != nil {
806					return fmt.Errorf("receipt %q action %d is not executable: %v", rcpt.ProposalID, i, err)
807				}
808				if ar.Treasury.Account != "treasury" || ar.Treasury.Before != simTreasury {
809					return fmt.Errorf("receipt %q action %d treasury before-balance mismatch", rcpt.ProposalID, i)
810				}
811				if simTreasury < amount || ar.Treasury.After != simTreasury-amount {
812					return fmt.Errorf("receipt %q action %d treasury after-balance mismatch", rcpt.ProposalID, i)
813				}
814				before := simBalances[account]
815				if ar.Recipient.Account != account || ar.Recipient.Before != before {
816					return fmt.Errorf("receipt %q action %d recipient before-balance mismatch", rcpt.ProposalID, i)
817				}
818				after, ok := addInt64(before, amount)
819				if !ok || ar.Recipient.After != after {
820					return fmt.Errorf("receipt %q action %d recipient after-balance mismatch", rcpt.ProposalID, i)
821				}
822				simTreasury -= amount
823				simBalances[account] = after
824			}
825		}
826		if simTreasury != state.Treasury {
827			return fmt.Errorf("treasury balance %d does not match receipt replay %d", state.Treasury, simTreasury)
828		}
829		if len(simBalances) != len(state.Balances) {
830			return fmt.Errorf("balance table has %d accounts, receipt replay yields %d", len(state.Balances), len(simBalances))
831		}
832		for account, balance := range state.Balances {
833			if simBalances[account] != balance {
834				return fmt.Errorf("balance of %q is %d but receipt replay yields %d", account, balance, simBalances[account])
835			}
836		}
837		// 已执行的提案必须有凭据；passed 提案不得有凭据（上面已部分保证）。
838		for _, p := range state.Proposals {
839			_, hasReceipt := seenReceipts[p.ID]
840			if p.State == "executed" && !hasReceipt {
841				return fmt.Errorf("proposal %q is executed without receipt", p.ID)
842			}
843		}
844		for _, p := range state.VoteProposals {
845			_, hasReceipt := seenReceipts[p.ID]
846			if p.State == "executed" && !hasReceipt {
847				return fmt.Errorf("voting proposal %q is executed without receipt", p.ID)
848			}
849		}
850		return nil
851	}
852	
853	// scanFrame 是重复键扫描的栈帧。
854	type scanFrame struct {
855		isArray bool
856		seen    map[string]bool
857		atValue bool // 对象帧：下一个待消费 token 是值而非键
858	}
859	
860	func rejectDuplicateKeys(raw []byte) error {
861		dec := json.NewDecoder(bytes.NewReader(raw))
862		var stack []*scanFrame
863		for {
864			tok, err := dec.Token()
865			if err == io.EOF {
866				if len(stack) != 0 {
867					return errors.New("unterminated object or array")
868				}
869				return nil
870			}
871			if err != nil {
872				return err
873			}
874			switch t := tok.(type) {
875			case json.Delim:
876				switch t {
877				case '{':
878					stack = append(stack, &scanFrame{seen: map[string]bool{}})
879					continue
880				case '[':
881					stack = append(stack, &scanFrame{isArray: true})
882					continue
883				case '}', ']':
884					if len(stack) == 0 {
885						return errors.New("unexpected closing delimiter")
886					}
887					stack = stack[:len(stack)-1]
888					// 关闭的容器本身是外层对象的某个“值”，消费完毕后外层等待下一个键。
889					if len(stack) > 0 && !stack[len(stack)-1].isArray {
890						stack[len(stack)-1].atValue = false
891					}
892					continue
893				}
894			default:
895				// 标量 token。
896			}
897			if len(stack) > 0 && !stack[len(stack)-1].isArray {
898				frame := stack[len(stack)-1]
899				if !frame.atValue {
900					key, ok := tok.(string)
901					if !ok {
902						return errors.New("object key must be a string")
903					}
904					if frame.seen[key] {
905						return fmt.Errorf("duplicate key %q", key)
906					}
907					frame.seen[key] = true
908					frame.atValue = true
909				} else {
910					frame.atValue = false
911				}
912			}
913		}
914	}
