136				t.Fatalf("action %d recipient mismatch: %+v", i, ar.Recipient)
137			}
138		}
139		if bal, _ := store.TreasuryBalance(); bal != 600 {
140			t.Fatalf("treasury = %d", bal)
141		}
142		if bal, _ := store.Balance("audits"); bal != 350 {
143			t.Fatalf("audits = %d", bal)
144		}
145		if bal, _ := store.Balance("ghost"); bal != 0 {
146			t.Fatalf("unknown account = %d, want 0", bal)
147		}
