169		}
170		if bal, _ := store.TreasuryBalance(); bal != 500 {
171			t.Fatalf("treasury changed on retry: %d", bal)
172		}
173		// 重试不追加凭据。
174		receipts, _ := store.Receipts()
175		if len(receipts) != 1 {
176			t.Fatalf("receipt count = %d, want 1", len(receipts))
177		}
178		if got, ok, _ := store.Receipt("gip-1"); !ok || got.ExecutedAt != 100 {
179			t.Fatalf("Receipt lookup failed: %+v %v", got, ok)
180		}
181		record, ok, _ := store.Proposal("gip-1")
182		if !ok || record.State != "executed" {
183			t.Fatalf("proposal state = %+v %v", record, ok)
184		}
185	}
