383	// dupKeyInject 在 balances 对象里注入一个重复键。
384	func dupKeyInject(good []byte) []byte {
385		s := string(good)
386		marker := "\"balances\": {"
387		idx := strings.Index(s, marker)
388		if idx < 0 {
389			// 空 balances 被渲染成 {}，改为含重复键的对象。
390			s = strings.Replace(s, "\"balances\": {}", "\"balances\": {\"x\": 1, \"x\": 2}", 1)
391			return []byte(s)
392		}
393		insertAt := idx + len(marker)
394		return []byte(s[:insertAt] + "\"dup\": 1, " + s[insertAt:])
395	}
