431		for i := 0; i < n; i++ {
432			wg.Add(1)
433			go func(i int) {
434				defer wg.Done()
435				<-start
436				receipts[i], results[i] = store.Execute("gip-1", int64(100+i))
437			}(i)
438		}
439		close(start)
440		wg.Wait()
441		successes := 0
442		for i, err := range results {
443			if err != nil {
444				t.Errorf("concurrent execute %d: %v", i, err)
445				continue
446			}
447			successes++
448			if receipts[i].ExecutedAt != receipts[0].ExecutedAt || receipts[i].Order != 0 {
449				t.Errorf("receipt mismatch at %d: %+v vs %+v", i, receipts[i], receipts[0])
450			}
451		}
452		if successes != n {
453			t.Fatalf("successes=%d, want %d (retries must return the same receipt, not error)", successes, n)
454		}
455		all, _ := store.Receipts()
456		if len(all) != 1 {
457			t.Fatalf("receipt count = %d, want 1", len(all))
458		}
459		if bal, _ := store.TreasuryBalance(); bal != 9995 {
460			t.Fatalf("treasury = %d, want 9995", bal)
461		}
462	}
