464	func TestConcurrentDifferentProposalsSpendCommittedBalance(t *testing.T) {
465		store, _ := openTempStore(t, 100)
466		defer store.Close()
467		const n = 40
468		// 每个提案花 10，资金库只够 10 个成功。
469		for i := 0; i < n; i++ {
470			mustRegister(t, store, "gip-"+itoa(i), 0, "transfer:a:10")
471		}
472		var wg sync.WaitGroup
473		start := make(chan struct{})
474		successes := make([]bool, n)
475		var counterMu sync.Mutex
476		successCount := 0
477		for i := 0; i < n; i++ {
478			wg.Add(1)
479			go func(i int) {
480				defer wg.Done()
481				<-start
482				_, err := store.Execute("gip-"+itoa(i), 0)
483				if err == nil {
484					counterMu.Lock()
485					successes[i] = true
486					successCount++
487					counterMu.Unlock()
488				} else if !errors.Is(err, ErrExecutionRejected) || !strings.Contains(err.Error(), "insufficient") {
489					t.Errorf("proposal %d unexpected err: %v", i, err)
490				}
491			}(i)
492		}
493		close(start)
494		wg.Wait()
495		if successCount != 10 {
496			t.Fatalf("successCount=%d, want exactly 10", successCount)
497		}
498		if bal, _ := store.TreasuryBalance(); bal != 0 {
499			t.Fatalf("treasury=%d, want 0", bal)
500		}
501		if bal, _ := store.Balance("a"); bal != 100 {
502			t.Fatalf("a=%d, want 100", bal)
503		}
504		receipts, _ := store.Receipts()
505		if len(receipts) != 10 {
506			t.Fatalf("receipts=%d, want 10", len(receipts))
507		}
508	}
