510	func TestPathSpellingsShareLock(t *testing.T) {
511		dir := t.TempDir()
512		cwd, err := os.Getwd()
513		if err != nil {
514			t.Fatal(err)
515		}
516		if err := os.Chdir(dir); err != nil {
517			t.Fatal(err)
518		}
519		defer os.Chdir(cwd)
