580	// TestNoPartialReadsDuringWrite 通过检查文件始终是合法 JSON 来观察原子性。
581	func TestAtomicFileIsAlwaysValid(t *testing.T) {
582		path := filepath.Join(t.TempDir(), "treasury.json")
583		store, err := InitTreasury(path, 100000)
