595		wg.Add(2)
596		go func() { // 写入方
597			defer wg.Done()
598			for i := 200; i < 400; i++ {
599				select {
600				case <-stop:
601					return
602				default:
603				}
604				id := "gip-" + itoa(i)
605				if existed, err := store.Register(id, 0, []string{"transfer:a:1"}); err == nil && !existed {
606					_, _ = store.Execute(id, 0)
607				}
608			}
609		}()
610		go func() { // 读取方：任何时刻打开都只能看到完整状态
611			defer wg.Done()
612			for {
613				select {
614				case <-stop:
615					return
616				default:
617				}
618				s, err := Open(path)
619				if err != nil {
620					if !errors.Is(err, ErrStateCorrupt) {
621						t.Errorf("reader unexpected err: %v", err)
622					}
623					// rename 之间不应存在损坏窗口；若观察到损坏说明非原子。
624					t.Errorf("observed non-atomic state file: %v", err)
625					return
626				}
627				if _, err := s.TreasuryBalance(); err != nil {
628					t.Errorf("read balance: %v", err)
629				}
