// isPreSnapshot 判断快照是否为转账前的完整状态：资金库 1000、无账户。
func isPreSnapshot(snap *BalanceSnapshot) bool {
	return snap.Treasury == 1000 && len(snap.Balances) == 0
}

// isPostSnapshot 判断快照是否为转账后的完整状态：资金库 850、audits=100、legal=50。
